        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assert(!reverted && !reentrantReverted && address(c).balance == 0);
    }
    receive() external payable {
        try c.withdrawAll() { reentrantReverted = false; } catch { reentrantReverted = true; }
    }
}

